// Handle Heartbeat webhook payloads and post to Slack #gru-community.
//
// Real Heartbeat payloads are minimal — just IDs. We discriminate trigger
// type by field presence and enrich via Heartbeat API calls (thread content,
// user names). Both GET /threads/{id} and GET /users/{id} are used.
//
// n8n Code nodes run in a VM sandbox — no global fetch, no process.env.
// We access env via $env and use require('https') (works because
// N8N_FUNCTION_ALLOW_BUILTIN=* is set on the container).

const https = require('https');

const HB_HOST = 'api.heartbeat.chat';
const HB_TOKEN = $env.HEARTBEAT_API_KEY || '';
const SLACK_CHANNEL = 'C0ASPB1L16D';
const COMMUNITY_BASE = 'https://community.tandemcoaching.academy';

const CHANNEL_MAP = {
  '4195ece0-b05c-417a-9501-56b848826835': { name: 'Announcements', emoji: '📣' },
};

function hbGet(path) {
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: HB_HOST,
        port: 443,
        path: `/v0${path}`,
        method: 'GET',
        headers: { Authorization: `Bearer ${HB_TOKEN}` },
        timeout: 15000,
      },
      (res) => {
        let chunks = '';
        res.setEncoding('utf8');
        res.on('data', (c) => (chunks += c));
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            try { resolve(JSON.parse(chunks)); }
            catch (e) { reject(new Error(`parse ${path}: ${e.message}`)); }
          } else {
            reject(new Error(`Heartbeat ${path} → HTTP ${res.statusCode}`));
          }
        });
      },
    );
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error(`timeout ${path}`)); });
    req.end();
  });
}

function htmlToPreview(html, maxLen = 300) {
  if (!html) return '';
  const stripped = String(html)
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|h[1-6]|div|li)>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\ufeff/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]+/g, ' ')
    .trim();
  if (stripped.length <= maxLen) return stripped;
  return stripped.slice(0, maxLen - 1).trimEnd() + '…';
}

function userLabel(u) {
  if (!u) return 'Unknown user';
  return u.name || u.email || u.id || 'Unknown user';
}

async function handleThreadCreate(body) {
  const thread = await hbGet(`/threads/${body.id}`);
  const ch = CHANNEL_MAP[thread.channelID];
  if (!ch) return null;
  const preview = htmlToPreview(thread.content) || '(no content)';
  const author = userLabel(thread.user);
  const url = thread.url || COMMUNITY_BASE;
  return (
    `:speech_balloon: *New post in ${ch.emoji} ${ch.name}* by *${author}*\n` +
    `>>>${preview}\n` +
    `<${url}|Open in community →>`
  );
}

async function handleDirectMessage(body) {
  const [sender, receiver] = await Promise.all([
    hbGet(`/users/${body.senderUserID}`).catch(() => null),
    hbGet(`/users/${body.receiverUserID}`).catch(() => null),
  ]);
  const senderName = userLabel(sender);
  const receiverName = userLabel(receiver);
  const url = `${COMMUNITY_BASE}/messages/${body.chatID}`;
  return (
    `:envelope: *New DM to ${receiverName}* from *${senderName}*\n` +
    `_(Heartbeat DMs don't include content in the webhook — click to read)_\n` +
    `<${url}|Open in community →>`
  );
}

const raw = $input.first().json;
const body = raw.body || raw;

let text;
try {
  if (body.chatMessageID && body.senderUserID) {
    text = await handleDirectMessage(body);
  } else if (body.id && body.channelID) {
    text = await handleThreadCreate(body);
  } else {
    text =
      `:question: *Unrecognized Heartbeat payload*\n` +
      `\`\`\`${JSON.stringify(body).slice(0, 2000)}\`\`\``;
  }
} catch (err) {
  text =
    `:warning: *Heartbeat webhook error:* ${err.message}\n` +
    `Payload: \`\`\`${JSON.stringify(body).slice(0, 1500)}\`\`\``;
}

if (!text) return [];
return [{ json: { channel: SLACK_CHANNEL, text, unfurl_links: false } }];
